--monitor= ,preferred,auto,auto
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
    output = "HDMI-A-2",
    mode = "1920x1080",
    position = "0x0",
    scale = "auto",
})

hl.monitor({
    output = "HDMI-A-1",
    mode = "1920x1080",
    position = "1920x0",
    scale = "auto",
})

