-- See https://wiki.hyprland.org/Configuring/Keywords/

-- Set programs that you use
local terminal = "ghostty"
local fileManager = "dolphin"
local menu = "rofi -show drun"

--################
--## AUTOSTART ###
--################

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:

-- exec-once = waybar & hyprpaper & firefox
hl.on("hyprland.start", function () 
   hl.exec_cmd(terminal)
   hl.exec_cmd("nm-applet")
   hl.exec_cmd("hyprpaper & firefox")
   hl.exec_cmd("waybar & foobar2000")
   hl.exec_cmd("discord")
   hl.exec_cmd("systemctl --user start hyprpolkitagent")
   --hl.exec_cmd("sudo systemctl enable --now docker")
   --hl.exec_cmd("sudo systemctl enable --now docker.service")
   --hl.exec_cmd("systemctl enable --now power-profiles-daemon.service")
   --hl.exec_cmd("/home/ben/.pyenv/versions/3.13.1/bin/beefweb_mpris")
 end)
